public static boolean startArmorInteract(Player player, EquipmentSlot slotType, TooltipKey modifierKey) {
  if (!player.isSpectator()) {
    ItemStack helmet = player.getItemBySlot(slotType);
    if (helmet.is(TinkerTags.Items.ARMOR)) {
      ToolStack tool = ToolStack.from(helmet);
      for (ModifierEntry entry : tool.getModifierList()) {
        if (entry.getHook(ModifierHooks.ARMOR_INTERACT).startInteract(tool, entry, player, slotType, modifierKey)) {
          // store data so we know when interaction started
          TinkerDataCapability.Holder data = TinkerDataCapability.getData(player);
          if (data != null) {
            data.computeIfAbsent(INTERACT_KEY).put(slotType, new ArmorInteractData(entry.getId(), player.tickCount));
          }
          break;
        }
      }
      return true;
    }
  }
  return false;
}

private static void handleKeyBindings(PlayerTickEvent event) {
  Minecraft minecraft = Minecraft.getInstance();
  if (minecraft.player != null && minecraft.player == event.player && event.phase == Phase.START && event.side == LogicalSide.CLIENT && !minecraft.player.isSpectator()) {

    // jumping in mid air for double jump
    // ensure we pressed the key since the last tick, holding should not use all your jumps at once
    boolean isJumping = minecraft.options.keyJump.isDown();
    if (!wasJumping && isJumping) {
      if (TinkerEffects.antigravity.get().antigravityJump(event.player)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.ANTIGRAVITY_JUMP);
      }
      else if (DoubleJumpHandler.extraJump(event.player)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.DOUBLE_JUMP);
      }
    }
    wasJumping = isJumping;

    // helmet interaction
    boolean isHelmetInteracting = HELMET_INTERACT.isDown();
    if (!wasHelmetInteracting && isHelmetInteracting) {
      TooltipKey key = SafeClientAccess.getTooltipKey();
      if (InteractionHandler.startArmorInteract(event.player, EquipmentSlot.HEAD, key)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.getStartHelmetInteract(key));
      }
    }
    if (wasHelmetInteracting && !isHelmetInteracting) {
      if (InteractionHandler.stopArmorInteract(event.player, EquipmentSlot.HEAD)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.STOP_HELMET_INTERACT);
      }
    }

    // leggings interaction
    boolean isLeggingsInteract = LEGGINGS_INTERACT.isDown();
    if (!wasLeggingsInteracting && isLeggingsInteract) {
      TooltipKey key = SafeClientAccess.getTooltipKey();
      if (InteractionHandler.startArmorInteract(event.player, EquipmentSlot.LEGS, key)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.getStartLeggingsInteract(key));
      }
    }
    if (wasLeggingsInteracting && !isLeggingsInteract) {
      if (InteractionHandler.stopArmorInteract(event.player, EquipmentSlot.LEGS)) {
        TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.STOP_LEGGINGS_INTERACT);
      }
    }

    wasHelmetInteracting = isHelmetInteracting;
    wasLeggingsInteracting = isLeggingsInteract;
  }
}

@Override
public void handleThreadsafe(Context context) {
  ServerPlayer player = context.getSender();
  if (player != null) {
    switch (this) {
      case DOUBLE_JUMP -> DoubleJumpHandler.extraJump(player);
      case ANTIGRAVITY_JUMP -> TinkerEffects.antigravity.get().antigravityJump(player);
      case START_HELMET_INTERACT, START_HELMET_INTERACT_SHIFT, START_HELMET_INTERACT_CONTROL, START_HELMET_INTERACT_ALT
        -> InteractionHandler.startArmorInteract(player, EquipmentSlot.HEAD, this.modifier);
      case STOP_HELMET_INTERACT -> InteractionHandler.stopArmorInteract(player, EquipmentSlot.HEAD);
      case START_LEGGINGS_INTERACT, START_LEGGINGS_INTERACT_SHIFT, START_LEGGINGS_INTERACT_CONTROL, START_LEGGINGS_INTERACT_ALT
        -> InteractionHandler.startArmorInteract(player, EquipmentSlot.LEGS, this.modifier);
      case STOP_LEGGINGS_INTERACT -> InteractionHandler.stopArmorInteract(player, EquipmentSlot.LEGS);
    }
  }
}

@Override
default boolean startInteract(IToolStackView tool, ModifierEntry modifier, Player player, EquipmentSlot slot, TooltipKey keyModifier) {
  if (!tool.isBroken() && keyModifier == TooltipKey.NORMAL && condition().matches(tool, modifier)) {
    HelmetChargingEffect.startUsingHelmet(tool, player, drawtimeMultiplier());
    return true;
  }
  return false;
}

@Override
default void stopInteract(IToolStackView tool, ModifierEntry modifier, Player player, EquipmentSlot slot, int chargeTime, ModifierEntry activeModifier) {
  if (chargeTime > 0 && !tool.isBroken() && condition().matches(tool, modifier)) {
    sling(tool, modifier, player, chargeTime, activeModifier);
  }
}

public static int startUsingHelmet(IToolStackView tool, LivingEntity living, float speedFactor) {
  int time = GeneralInteractionModifierHook.startDrawing(tool, living, speedFactor);
  living.addEffect(new MobEffectInstance(TinkerModifiers.helmetCharging.get(), time + 20, 0, true, false, true));
  return time;
}

static int startDrawing(IToolStackView tool, LivingEntity living, float speedFactor) {
  int drawtime = getDrawtime(tool, living, speedFactor);
  tool.getPersistentData().putInt(KEY_DRAWTIME, drawtime);
  return drawtime;
}

static int getDrawtime(IToolStackView tool, LivingEntity living, float speedFactor) {
  return (int)Math.ceil(20f * speedFactor / ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.DRAW_SPEED));
}

static float getToolCharge(IToolStackView tool, float chargeTime) {
  if (chargeTime < 0) {
    return 0;
  }
  float charge = chargeTime / tool.getPersistentData().getInt(KEY_DRAWTIME);
  charge = (charge * charge + charge * 2) / 3;
  if (charge > 1) {
    charge = 1;
  }
  return charge;
}

static void finishUsing(IToolStackView tool) {
  ModDataNBT persistentData = tool.getPersistentData();
  persistentData.remove(KEY_ACTIVE_MODIFIER);
  persistentData.remove(KEY_DRAWTIME);
}

@Override
public void sling(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int chargeTime, ModifierEntry activeModifier) {
  Level level = entity.level();
  if (!level.isClientSide && entity instanceof Player player) {
    float charge = GeneralInteractionModifierHook.getToolCharge(tool, chargeTime);
    if (charge > 0) {
      Vec3 start = player.getEyePosition(1F);
      Vec3 look = player.getLookAngle();
      Vec3 direction = start.add(look.x * RANGE, look.y * RANGE, look.z * RANGE);
      AABB bb = player.getBoundingBox().expandTowards(look.x * RANGE, look.y * RANGE, look.z * RANGE).expandTowards(1, 1, 1);

      EntityHitResult hit = ProjectileUtil.getEntityHitResult(level, player, start, direction, bb, e -> e instanceof LivingEntity);
      if (hit != null) {
        LivingEntity target = (LivingEntity)hit.getEntity();
        if (this.target.matches(target)) {
          double targetDist = start.distanceToSqr(target.getEyePosition(1F));

          // cancel if there's a block in the way
          BlockHitResult mop = ModifiableItem.blockRayTrace(level, player, ClipContext.Fluid.NONE);
          if (mop.getType() != HitResult.Type.BLOCK || targetDist < mop.getBlockPos().distToCenterSqr(start)) {
            // melee tools also do damage as a treat
            boolean didBonk = false;
            if (damageMultiplier > 0 && ToolAttackUtil.isAttackable(entity, target) && EntityInteractionModifierHook.isMelee(tool)) {
              didBonk = true;
              ModDataNBT data = tool.getPersistentData();
              data.putBoolean(IS_BONKING, true);
              InteractionHand hand = player.getUsedItemHand();
              ToolAttackContext.Builder builder = ToolAttackContext.attacker(entity).target(target).hand(hand).cooldown(Math.min(1, charge));
              if (hand == InteractionHand.MAIN_HAND) {
                builder.applyAttributes();
              } else {
                builder.toolAttributes(tool);
              }
              ToolAttackUtil.performAttack(tool, builder.build());
              data.remove(IS_BONKING);
            }

            // send it flying
            float inaccuracy = ModifierUtil.getInaccuracy(tool, player) * 0.0075f;
            RandomSource random = player.getRandom();
            float multiplier = charge * this.forceMultiplier.compute(modifier);
            float force = SlingForceModifierHook.modifySlingForce(tool, entity, target, modifier, SlingModule.getPower(tool, player) * multiplier, multiplier);
            Vec3 angle = Vec3.ZERO;
            if (force > 0) {
              // skip the bonk if we lack force, but the attack is fine
              angle = SlingAngleModifierHook.modifySlingAngle(tool, entity, target, modifier, force, multiplier, new Vec3(
                (-look.x + random.nextGaussian() * inaccuracy),
                0,
                (-look.z + random.nextGaussian() * inaccuracy)
              ));
              target.knockback(force, angle.x, angle.z);
              if (target instanceof ServerPlayer playerMP) {
                TinkerNetwork.getInstance().sendVanillaPacket(new ClientboundSetEntityMotionPacket(target), playerMP);
              }
              didBonk = true;
            }

            // if we dealt damage or knockback, apply bonk effects
            if (didBonk) {
              // spawn the bonk particle
              ToolAttackUtil.spawnAttackParticle(TinkerTools.bonkAttackParticle.get(), player, 0.6d);

              // modifier callbacks
              SlingLaunchModifierHook.afterSlingLaunch(tool, entity, target, modifier, force, multiplier, angle);

              // cooldowns and stuff
              level.playSound(null, player.getX(), player.getY(), player.getZ(), Sounds.BONK.getSound(), player.getSoundSource(), 1, 0.5f);
              player.causeFoodExhaustion(0.2F);
              player.getCooldowns().addCooldown(tool.getItem(), 3);
              ToolDamageUtil.damageAnimated(tool, 1, entity, entity.getUsedItemHand(), modifier.getId());
              return;
            }
          }
        }
      }
    }
    // play failure sound
    if (ModifierUtil.isActiveModifier(tool, modifier, activeModifier)) {
      level.playSound(null, player.getX(), player.getY(), player.getZ(), Sounds.BONK.getSound(), player.getSoundSource(), 1, 1f);
    }
  }
}

@Override
public float beforeMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damage, float baseKnockback, float knockback) {
  if (tool.getPersistentData().getBoolean(IS_BONKING)) {
    return 0;
  }
  return knockback;
}

@Override
public float getMeleeDamage(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float baseDamage, float damage) {
  if (damageMultiplier != 1 && tool.getPersistentData().getBoolean(IS_BONKING)) {
    damage *= damageMultiplier;
  }
  return damage;
}

@SuppressWarnings("DataFlowIssue")
@Nullable
public static TinkerDataCapability.Holder getData(LivingEntity entity) {
  return entity.getCapability(CAPABILITY).orElse(null);
}

@Override
public void run() {
  // called when capabilities invalidate, just invalidate but preserve the old data
  // (as if they revive the equipment change event does not fire again, see dimension change)
  Holder oldData = data.orElse(new Holder());
  data.invalidate();
  data = LazyOptional.of(() -> oldData);
}

