public static void addBounceHandler(LivingEntity entity, @Nullable Vec3 bounce) {
  // no fake players PlayerTick event
  if (entity instanceof FakePlayer) {
    return;
  }
  // update bounce info
  BounceInfo info = BOUNCING_ENTITIES.get(entity);
  if (info == null) {
    BOUNCING_ENTITIES.put(entity, new BounceInfo(entity, bounce));
  } else if (bounce != null) {
    // updated bounce if needed
    info.bounce = bounce;
    // add one to the tick as there is a 1 tick delay between falling and ticking for many entities
    info.bounceTick = entity.tickCount + 1;
    Vec3 motion = entity.getDeltaMovement();
    info.lastMagSq = motion.x * motion.x + motion.z * motion.z;
    info.lastAngle = Mth.atan2(motion.z, motion.x);
  }
}

public static void addBounceHandler(LivingEntity entity) {
  addBounceHandler(entity, null);
}

public BounceInfo(LivingEntity entity, @Nullable Vec3 bounce) {
  this.bounce = bounce;
  if (bounce != null) {
    // add one to the tick as there is a 1 tick delay between falling and ticking for many entities
    this.bounceTick = entity.tickCount + 1;
  } else {
    this.bounceTick = 0;
  }
  Vec3 motion = entity.getDeltaMovement();
  this.lastMagSq = motion.x * motion.x + motion.z * motion.z;
}

private static void serverStopping(ServerStoppingEvent event) {
  BOUNCING_ENTITIES.clear();
}

public static void init() {
  MinecraftForge.EVENT_BUS.addListener(SlimeBounceHandler::onLivingTick);
  MinecraftForge.EVENT_BUS.addListener(SlimeBounceHandler::serverStopping);
}

@SubscribeEvent
static void bounceOnFall(LivingFallEvent event) {
  LivingEntity living = event.getEntity();
  // using fall distance as the event distance could be reduced by jump boost
  if (living == null || (living.fallDistance < 3 && living.getDeltaMovement().y > -0.3) || living.fallDistance <= 0.5f + living.getAttributeValue(ForgeMod.STEP_HEIGHT_ADDITION.get())) {
    return;
  }
  // can the entity bounce?
  if (living.getAttributeValue(TinkerAttributes.BOUNCY.get()) < 1) {
    return;
  }

  // reduced fall damage when crouching
  if (living.isSuppressingBounce()) {
    event.setDamageMultiplier(0.5f);
    return;
  } else {
    event.setDamageMultiplier(0.0f);
  }

  // server players behave differently than non-server players, they have no velocity during the event, so we need to reverse engineer it
  Vec3 motion = living.getDeltaMovement();
  if (living instanceof ServerPlayer) {
    // velocity is lost on server players, but we dont have to defer the bounce
    double gravity = living.getAttributeValue(ForgeMod.ENTITY_GRAVITY.get());
    double time = Math.sqrt(living.fallDistance / gravity);
    double velocity = gravity * time;
    living.setDeltaMovement(motion.x / 0.975f, velocity, motion.z / 0.975f);
    living.hurtMarked = true;

    // preserve momentum
    SlimeBounceHandler.addBounceHandler(living);
  } else {
    // for non-players, need to defer the bounce
    // only slow down half as much when bouncing
    float factor = living.fallDistance < 2 ? -0.7f : -0.9f;
    living.setDeltaMovement(motion.x / 0.975f, motion.y * factor, motion.z / 0.975f);
    SlimeBounceHandler.addBounceHandler(living, living.getDeltaMovement());
  }
  // update airborn status
  event.setDistance(0.0F);
  if (!living.level().isClientSide) {
    living.hasImpulse = true;
    event.setCanceled(true);
    living.setOnGround(false); // need to be on ground for server to process this event
  }
  living.playSound(Sounds.SLIMY_BOUNCE.getSound(), 1f, 1f);
}

@SubscribeEvent
void commonSetupEvent(FMLCommonSetupEvent event) {
  SlimeBounceHandler.init();
}

