        ItemStack stack = new ItemStack((Void) null);
        Services.PLATFORM.setEntityToItemStack(stack, entity);
        ENTITY_EMPTY_STACK_MAP.put(entity, stack);
    }
    return ENTITY_EMPTY_STACK_MAP.get(entity);
